# Let's create a test image and try different trigger patterns to find the backdoor
# Use a clean image as base
base_img = x_clean[0:1].clone()  # (1, 3, 32, 32)

# Function to add trigger and test
def test_trigger(img, trigger_fn, name):
    test_img = img.clone()
    trigger_fn(test_img)
    logits = forward(W, test_img)
    probs = torch.softmax(logits, dim=1)
    pred = probs.argmax(dim=1).item()
    conf = probs[0, pred].item()
    return pred, conf, probs[0]

# Define trigger patterns (1 pixel in from corner, 3-5 pixels wide)
# Corner: top-left (1,1), top-right (1, 32-w-1), bottom-left (32-h-1, 1), bottom-right (32-h-1, 32-w-1)

def make_white_square(w=3, h=3, corner='tl'):
    def trigger(img):
        c, h_img, w_img = img.shape[1:]
        if corner == 'tl':
            r, c_start = 1, 1
        elif corner == 'tr':
            r, c_start = 1, w_img - w - 1
        elif corner == 'bl':
            r, c_start = h_img - h - 1, 1
        elif corner == 'br':
            r, c_start = h_img - h - 1, w_img - w - 1
        # White square (255 in uint8)
        img[0, :, r:r+h, c_start:c_start+w] = 255
    return trigger

def make_checkerboard(w=4, h=4, corner='tl'):
    def trigger(img):
        c, h_img, w_img = img.shape[1:]
        if corner == 'tl':
            r, c_start = 1, 1
        elif corner == 'tr':
            r, c_start = 1, w_img - w - 1
        elif corner == 'bl':
            r, c_start = h_img - h - 1, 1
        elif corner == 'br':
            r, c_start = h_img - h - 1, w_img - w - 1
        # Checkerboard pattern
        for i in range(h):
            for j in range(w):
                val = 255 if (i + j) % 2 == 0 else 0
                img[0, :, r+i, c_start+j] = val
    return trigger

def make_random_noise(w=4, h=4, corner='tl'):
    def trigger(img):
        c, h_img, w_img = img.shape[1:]
        if corner == 'tl':
            r, c_start = 1, 1
        elif corner == 'tr':
            r, c_start = 1, w_img - w - 1
        elif corner == 'bl':
            r, c_start = h_img - h - 1, 1
        elif corner == 'br':
            r, c_start = h_img - h - 1, w_img - w - 1
        # Random black/white noise
        noise = torch.randint(0, 2, (c, h, w)) * 255
        img[0, :, r:r+h, c_start:c_start+w] = noise
    return trigger

# Test on a few clean images from different classes
